"g|en|A1|A/an (indefinite article)":[["I need a coffee.","","Saya butuh secangkir kopi.","a","secangkir"],["She has an apple.","","Dia punya sebuah apel.","an","sebuah"],["He is a teacher.","","Dia seorang guru.","a teacher","seorang"],["It is an orange.","","Itu sebuah jeruk.","an orange","sebuah"],["I'm looking for a pen.","","Saya mencari sebuah pulpen.","a","sebuah"],["We live in a small house.","","Kami tinggal di sebuah rumah kecil.","a small","sebuah"],["My mother is an engineer.","","Ibuku seorang insinyur.","an","seorang"],["Can I have a glass of water?","","Bolehkah saya minta segelas air?","a glass","segelas"],["There is an old man at the door.","","Ada seorang pria tua di depan pintu.","an old","seorang"],["She wants a new bike for her birthday.","","Dia ingin sebuah sepeda baru untuk ulang tahunnya.","a new","sebuah"],["He eats an egg and drinks milk every morning.","","Dia makan sebutir telur dan minum susu setiap pagi.","an egg","sebutir"],["My brother works in an office downtown.","","Kakakku bekerja di sebuah kantor di pusat kota.","an","sebuah"],["I want to buy a gift for my teacher's birthday.","","Saya ingin membeli sebuah hadiah untuk ulang tahun guru saya.","a gift","sebuah"],["It takes an hour to get to my grandmother's house.","","Perlu waktu satu jam untuk sampai ke rumah nenek saya.","an hour","satu"],["We saw a funny movie last night, and the actors were great.","","Kami menonton sebuah film lucu tadi malam, dan para aktornya hebat.","a funny","sebuah"]],
"g|en|A1|Artikel untuk profesi":[["I am a teacher.","","Saya seorang guru.","a teacher","seorang"],["She is a doctor.","","Dia seorang dokter.","a doctor","seorang"],["He is an engineer.","","Dia seorang insinyur.","an engineer","seorang"],["Are you a student?","","Apakah kamu seorang siswa?","a student","seorang"],["My father is a driver.","","Ayahku seorang sopir.","a driver","seorang"],["My mother is an artist.","","Ibuku seorang seniman.","an artist","seorang"],["Is your brother a nurse?","","Apakah kakakmu seorang perawat?","a nurse","seorang"],["Mr. Chen is a cook at the Grand Hotel.","","Pak Chen seorang juru masak di Grand Hotel.","a cook","seorang"],["My neighbor is a police officer.","","Tetanggaku seorang polisi.","a police officer","seorang"],["She wants to be a pilot one day.","","Dia ingin menjadi seorang pilot suatu hari nanti.","a pilot","seorang"],["My aunt is an actress, and she lives in Jakarta.","","Bibiku seorang aktris, dan dia tinggal di Jakarta.","an actress","seorang"],["Her husband is a farmer, and he grows rice.","","Suaminya seorang petani, dan dia menanam padi.","a farmer","seorang"],["I'm not a singer, but I love to sing in the shower.","","Saya bukan seorang penyanyi, tetapi saya suka bernyanyi di kamar mandi.","a singer","seorang"],["My best friend is a dentist, and he works near the station.","","Sahabatku seorang dokter gigi, dan dia bekerja dekat stasiun.","a dentist","seorang"],["My cousin is an English teacher, and she works in a school in Bali.","","Sepupuku seorang guru bahasa Inggris, dan dia bekerja di sebuah sekolah di Bali.","an English teacher","seorang"]],
"g|en|A1|Like / love / want + noun / to-V":[["I like coffee.","","Saya suka kopi.","like","suka"],["She loves cats.","","Dia sangat suka kucing.","loves","suka"],["We want water.","","Kami mau air.","want","mau"],["He wants a new bike.","","Dia mau sepeda baru.","wants","mau"],["I like to swim.","","Saya suka berenang.","like","suka"],["They want to go home.","","Mereka mau pulang.","want","mau"],["Do you like pizza?","","Apakah kamu suka pizza?","like","suka"],["My sister loves to dance.","","Kakakku suka menari.","loves","suka"],["What do you want to eat?","","Kamu mau makan apa?","want","mau"],["I don't like hot weather.","","Saya tidak suka cuaca panas.","like","suka"],["Tom wants to play football after school.","","Tom mau bermain sepak bola sepulang sekolah.","wants","mau"],["My parents love to travel in the summer.","","Orang tuaku suka bepergian pada musim panas.","love","suka"],["We want a table for four near the window, please.","","Kami mau meja untuk empat orang dekat jendela.","want","mau"],["She likes reading books, but she doesn't like watching TV.","","Dia suka membaca buku, tetapi tidak suka menonton TV.","likes","suka"],["I love my job because I want to help people every day.","","Saya sangat suka pekerjaanku karena saya ingin membantu orang setiap hari.","love","suka"]],
"g|en|A1|Common noun vs proper noun":[["He sat on the chair.","","Dia duduk di kursi itu.","chair","kursi"],["Anna lives in Paris.","","Anna tinggal di Paris.","Paris","Paris"],["The dog is big.","","Anjing itu besar.","dog","Anjing"],["My teacher is Mr. Brown.","","Guruku adalah Pak Brown.","Brown","Brown"],["We visit Bali in July.","","Kami mengunjungi Bali pada bulan Juli.","Bali","Bali"],["The river is very long.","","Sungai itu sangat panjang.","river","Sungai"],["Maria is a girl from Spain.","","Maria adalah gadis dari Spanyol.","Spain","Spanyol"],["My brother has a cat named Milo.","","Kakakku punya seekor kucing bernama Milo.","Milo","Milo"],["The city is beautiful in spring.","","Kota itu indah pada musim semi.","city","Kota"],["Our school is on Main Street.","","Sekolah kami ada di Jalan Main.","Main","Main"],["I study English every Monday at the library.","","Saya belajar bahasa Inggris setiap hari Senin di perpustakaan.","Monday","Senin"],["My friend Tom comes from Canada, and he loves the mountains.","","Temanku Tom berasal dari Kanada, dan dia suka pegunungan.","Canada","Kanada"],["Lake Toba is the biggest lake in Indonesia.","","Danau Toba adalah danau terbesar di Indonesia.","Toba","Toba"],["She bought a table and four chairs at the market.","","Dia membeli sebuah meja dan empat kursi di pasar.","market","pasar"],["My uncle lives in Surabaya, and he works for a company near the harbor.","","Pamanku tinggal di Surabaya, dan dia bekerja di perusahaan dekat pelabuhan.","Surabaya","Surabaya"]],
"g|en|A1|Countable noun: a/an dan bentuk jamak":[["I have a cup.","","Saya punya sebuah cangkir.","a cup","sebuah"],["I have two cups.","","Saya punya dua cangkir.","two cups","dua"],["She has an egg.","","Dia punya sebutir telur.","an egg","sebutir"],["We need three chairs.","","Kami butuh tiga kursi.","three chairs","tiga"],["There is a car outside.","","Ada sebuah mobil di luar.","a car","sebuah"],["There are four cars outside.","","Ada empat mobil di luar.","four cars","empat"],["He has many friends.","","Dia punya banyak teman.","many friends","banyak"],["She has several books.","","Dia punya beberapa buku.","several books","beberapa"],["I want an apple and two bananas.","","Saya mau sebuah apel dan dua pisang.","two bananas","dua"],["My sister has a dog and three cats.","","Kakakku punya seekor anjing dan tiga kucing.","three cats","tiga"],["We don't have many questions today.","","Kami tidak punya banyak pertanyaan hari ini.","many questions","banyak"],["She bought a new bag and several pens for school.","","Dia membeli sebuah tas baru dan beberapa pulpen untuk sekolah.","several pens","beberapa"],["There is a student at the door, and there are ten students in the hall.","","Ada seorang murid di pintu, dan ada sepuluh murid di aula.","ten students","sepuluh"],["My grandfather has an old watch and two clocks in his room.","","Kakekku punya sebuah jam tangan tua dan dua jam dinding di kamarnya.","two clocks","dua"],["Many trains stop here, but only one goes to Bogor.","","Banyak kereta berhenti di sini, tetapi hanya satu yang ke Bogor.","Many trains","Banyak"]],
